struct fcfs{
    int bursttime;
    int waitingtime;
    int totaltime;
}p[10];

int main() { // Changed `void main()` to `int main()` which is the standard signature.
    int n;
    printf("Enter the number of processes: ");
    scanf("%d", &n);
    printf("Enter the burst time of the following\n");

    for(int i=0; i<n; i++) {
        printf("Enter the process %d burst time: ", i+1);
        scanf("%d", &p[i].bursttime);
    }

    p[0].waitingtime = 0; // First process always has a waiting time of 0 in FCFS.
    p[0].totaltime = p[0].bursttime; // Total time for the first process is its burst time.

    printf("The waiting time of process 1 is 0\n"); // Directly print the waiting time for the first process.
    printf("The turnaround time of process 1 is %d\n", p[0].totaltime);

    int total_waiting_time = 0; // To accumulate all waiting times to compute the average later.

    for(int i=1; i<n; i++) {
        p[i].waitingtime = p[i-1].waitingtime + p[i-1].bursttime; // Waiting time is the sum of the burst time and waiting time of the previous process.
        p[i].totaltime = p[i].waitingtime + p[i].bursttime; // Total time is the sum of its burst time and waiting time.
        printf("The waiting time of process %d is %d\n", i+1, p[i].waitingtime);
        printf("The turnaround time of process %d is %d\n", i+1, p[i].totaltime);
        total_waiting_time += p[i].waitingtime;
    }

    float average = (float)total_waiting_time / n;
    printf("The average waiting time is %f\n", average);

    return 0;
}
```

This program accurately follows the FCFS scheduling algorithm's rules for calculating waiting and total (turnaround) times, and it calculates the average waiting time correctly.

