    bottom = std::max(a.y, b.y);
    front = std::min(a.z, b.z);
    back = std::max(a.z, b.z);
}

// 两个浮点数是否在浮点误差内相等
bool isClose(const float a, const float b)
{
    return std::abs(a - b) < FloatTol;
}

// 两个浮点数是否一定有序，即使考虑浮点误差
bool isLess(const float a, const float b)
{
    return a + FloatTol < b;
}

// 三点是否共线
bool collinear(const CustomPoint& a, const CustomPoint& b, const CustomPoint& c)
{
    const float v1x = b.x - a.x;
    const float v1y = b.y - a.y;
    const float v1z = b.z - a.z;

    const float v2x = c.x - b.x;
    const float v2y = c.y - b.y;
    const float v2z = c.z - b.z;

    const float cross_x = v1y * v2z - v1z * v2y;
    const float cross_y = v1z * v2x - v1x * v2z;
    const float cross_z = v1x * v2y - v1y * v2x;

    return isClose(cross_x, 0.0f) && isClose(cross_y, 0.0f) && isClose(cross_z, 0.0f);
}

// 对浮点数组排序并去重
void sortAndDedup(std::vector<float>& v)
{
    std::sort(v.begin(), v.end());
    const auto last = std::unique(v.begin(), v.end(), isClose);
    v.erase(last, v.end());
}

// 在排好序的浮点数组中用二分法搜索给定数值的编号，已知数组非空
// C++20有std::binary_search
size_t searchSorted(const std::vector<float>& v, const float target)
{
    // 中线的起点和终点可能为画布边界，因此超出v的范围
    if (target <= v[0])
    {
        return 0;
    }

    if (target >= v.back())
    {
        return v.size() - 1;
    }

    const auto it = std::lower_bound(v.cbegin(), v.cend(), target, isLess);
    return std::distance(v.cbegin(), it);
}

// 在排好序的x y z坐标中搜索给定点
DiscretePoint searchSortedPoint(const std::vector<float>& xs, const std::vector<float>& ys,
                                const std::vector<float>& zs, const CustomPoint& p)
{
    return {searchSorted(xs, p.x), searchSorted(ys, p.y), searchSorted(zs, p.z)};
}

}  // namespace routenodes
